package net.civeira.phylax.feature.identity.tenant.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenant.domain.Tenant;
import net.civeira.phylax.feature.identity.tenant.domain.valueobject.DomainVO;

class DomainValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of domain of tenant")
  void test_domain_value_holder_assign_plain_value() {
    Object holder = new Object();
    DomainValueHolder<Object> value = new DomainValueHolder<>(holder);
    Assertions.assertSame(holder, value.domain("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getDomainValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getDomain().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of domain of tenant")
  void test_domain_value_holder_assign_value_object() {
    Object holder = new Object();
    DomainValueHolder<Object> value = new DomainValueHolder<>(holder);
    DomainVO vo = DomainVO.from("one");
    Assertions.assertFalse(value.getDomainValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.domain(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDomainValue().orElseThrow());
    Assertions.assertSame(holder, value.domain(Optional.empty()));
    Assertions.assertFalse(value.getDomainValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.domain(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDomainValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of domain of tenant against the original")
  void test_domain_value_holder_read() {
    Object holder = new Object();
    DomainValueHolder<Object> value = new DomainValueHolder<>(holder);
    DomainVO vo = DomainVO.from("one");
    DomainVO other = DomainVO.from("one");
    Tenant original = Mockito.mock(Tenant.class);
    Mockito.when(original.getDomainValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDomain(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readDomain(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.domain(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDomain(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDomain(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of domain of tenant")
  void test_domain_value_holder_unset() {
    Object holder = new Object();
    DomainValueHolder<Object> value = new DomainValueHolder<>(holder);
    DomainVO vo = DomainVO.from("one");
    value.domain(vo);
    Assertions.assertSame(holder, value.unsetDomainIfMatches("domain_other"));
    Assertions.assertTrue(value.getDomainValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDomainIfMatches("domain"));
    Assertions.assertFalse(value.getDomainValue().isPresent(),
        "The field name must clear the value");
    value.domain(vo);
    Assertions.assertSame(holder, value.unsetDomain());
    Assertions.assertFalse(value.getDomainValue().isPresent(), "Unset must clear the value");
  }
}
